package com.hmdp.upgrade;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

@Service
public class LocalOperations {
    final LocalData d;private final LocalLifeConfiguration config;private final LocalAccounts accounts;
    public LocalOperations(JdbcTemplate db,Transactions tx,ObjectMapper json,LocalLifeConfiguration config,LocalAccounts accounts){d=new LocalData(db,tx,json);this.config=config;this.accounts=accounts;}
    public Object overview(long user){accounts.requireOperator(user);return Map.of("shops",d.db.queryForObject("SELECT COUNT(*) FROM ux_local_shop",Integer.class),"reviews",d.db.queryForObject("SELECT COUNT(*) FROM ux_review WHERE state='PUBLISHED'",Integer.class),"coupons",d.db.queryForObject("SELECT COUNT(*) FROM ux_user_coupon",Integer.class),"reports",d.db.queryForObject("SELECT COUNT(*) FROM ux_content_report WHERE state='OPEN'",Integer.class),"feedback",d.db.queryForObject("SELECT COUNT(*) FROM ux_feedback WHERE state<>'RESOLVED'",Integer.class));}
    public List<Map<String,Object>> policies(String query){config.require();String q=LocalData.text(query,0,200);var now=d.now();var rows=d.rows("SELECT id,title,category,keywords,body,version,effective_at FROM ux_policy WHERE state='PUBLISHED' AND effective_at<=? ORDER BY category,title LIMIT 100",LocalData.at(now));
        var scores=new HashMap<String,Integer>();for(var row:rows){int score=0;String title=row.get("title").toString();if(!q.isEmpty()){if(q.contains(title)||title.contains(q))score+=20;for(String word:row.get("keywords").toString().split("[,， ]"))if(word.length()>1&&q.contains(word))score+=Math.min(10,word.length()*2);if(q.contains(row.get("category").toString()))score++;}scores.put(row.get("id").toString(),score);}
        return rows.stream().filter(x->q.isEmpty()||scores.get(x.get("id").toString())>0).sorted(Comparator.<Map<String,Object>>comparingInt(x->scores.get(x.get("id").toString())).reversed()).limit(q.isEmpty()?30:5).peek(x->{x.remove("keywords");x.put("sourcePath","/v2/local/policies?id="+x.get("id"));x.put("checkedAt",now);}).toList();}
    public List<Map<String,Object>> policy(String id){config.require();var rows=d.rows("SELECT id,title,category,body,version,effective_at FROM ux_policy WHERE id=? AND state='PUBLISHED' AND effective_at<=?",id,LocalData.at(d.now()));rows.forEach(x->{x.put("sourcePath","/v2/local/policies?id="+id);x.put("checkedAt",d.now());});return rows;}
    public Object allPolicies(long user){accounts.requireOperator(user);return Map.of("items",d.rows("SELECT * FROM ux_policy ORDER BY created_at DESC LIMIT 200"));}
    public Object savePolicy(long user,String previous,Map<String,Object> b){accounts.requireOperator(user);String title=LocalData.text(b.get("title"),2,120),category=LocalData.text(b.get("category"),1,30),keywords=LocalData.text(b.get("keywords"),2,250),body=LocalData.text(b.get("body"),10,2000),state=LocalData.text(b.getOrDefault("state","PUBLISHED"),1,16);if(!Set.of("DRAFT","PUBLISHED","ARCHIVED").contains(state))throw new Problem(400,"LOCAL_INVALID_INPUT");
        return d.tx.run(()->{long version=1;if(previous!=null){var old=d.one("SELECT * FROM ux_policy WHERE id=? FOR UPDATE",previous);if(((Number)old.get("version")).longValue()!=LocalData.version(b))throw new Problem(409,"LOCAL_VERSION_CONFLICT");version=((Number)old.get("version")).longValue()+1;d.db.update("UPDATE ux_policy SET state='ARCHIVED' WHERE id=?",previous);}
            String id=LocalData.id();d.db.update("INSERT INTO ux_policy(id,title,category,keywords,body,version,state,effective_at,created_at) VALUES(?,?,?,?,?,?,?,?,?)",id,title,category,keywords,body,version,state,LocalData.at(d.now()),LocalData.at(d.now()));d.audit(user,"POLICY_VERSION",id,title+" v"+version);return d.one("SELECT * FROM ux_policy WHERE id=?",id);});}
    public Object feedback(long user,Map<String,Object> b){config.require();accounts.limit("feedback:"+user,5);String key=LocalData.text(b.get("requestKey"),8,64),title=LocalData.text(b.get("title"),2,120),body=LocalData.text(b.get("body"),10,1500);
        return d.tx.run(()->{d.lockUser(user);var old=d.rows("SELECT * FROM ux_feedback WHERE user_id=? AND request_key=?",user,key);if(!old.isEmpty()){var record=old.get(0);if(!record.get("title").equals(title)||!record.get("body").equals(body))throw new Problem(409,"LOCAL_KEY_CONFLICT");return record;}
            String id=LocalData.id();d.db.update("INSERT INTO ux_feedback(id,user_id,request_key,title,body,state,created_at,updated_at) VALUES(?,?,?,?,?,'OPEN',?,?)",id,user,key,title,body,LocalData.at(d.now()),LocalData.at(d.now()));return d.one("SELECT * FROM ux_feedback WHERE id=?",id);});}
    public Object myFeedback(long user){config.require();return Map.of("items",d.rows("SELECT id,title,body,state,resolution,created_at,updated_at FROM ux_feedback WHERE user_id=? ORDER BY created_at DESC LIMIT 100",user),"reports",d.rows("SELECT id,review_id,reason,state,resolution,created_at FROM ux_content_report WHERE user_id=? ORDER BY created_at DESC LIMIT 100",user));}
    public Object issues(long user,String type){accounts.requireOperator(user);String table=table(type);return Map.of("items",d.rows("SELECT * FROM "+table+" ORDER BY updated_at DESC LIMIT 100"));}
    private String table(String type){return switch(type){case "feedback"->"ux_feedback";case "reports"->"ux_content_report";default->throw new Problem(400,"LOCAL_INVALID_INPUT");};}
    public Object resolve(long user,String type,String id,Map<String,Object> b){accounts.requireOperator(user);String table=table(type),state=LocalData.text(b.get("state"),1,16),resolution=LocalData.text(b.get("resolution"),5,500);Set<String> valid=type.equals("feedback")?Set.of("IN_PROGRESS","RESOLVED"):Set.of("RESOLVED","DISMISSED");if(!valid.contains(state))throw new Problem(400,"LOCAL_INVALID_INPUT");
        return d.tx.run(()->{var old=d.one("SELECT * FROM "+table+" WHERE id=? FOR UPDATE",id);if(!Set.of("OPEN","IN_PROGRESS").contains(old.get("state")))throw new Problem(409,"LOCAL_VERSION_CONFLICT");d.db.update("UPDATE "+table+" SET state=?,resolution=?,operator_id=?,updated_at=? WHERE id=?",state,resolution,user,LocalData.at(d.now()),id);d.audit(user,"ISSUE_"+type.toUpperCase(Locale.ROOT),id,state);return d.one("SELECT * FROM "+table+" WHERE id=?",id);});}
}
